shader.vertex:
attribute vec3 Position;
attribute vec4 Color;
attribute vec2 TexCoord;
attribute vec4 RenderData;
attribute float Scale;
attribute float Time;
attribute float Strength;

varying vec4 Color0;
varying vec2 TexCoord0;
varying vec4 RenderDataOut;
varying float ScaleOut;
varying float TimeOut;
varying float StrengthOut;

uniform mat4 Transform;
void main(void)
{
    RenderDataOut = RenderData;
    // Passing data to fragment shader
    ScaleOut = Scale;           
    TimeOut = Time;
    StrengthOut = Strength;
    Color0 = Color;
    TexCoord0 = TexCoord;

    gl_Position = Transform * vec4(Position.xyz, 1.0);
}

shader.fragment:
varying lowp vec4 Color0;
varying mediump vec2 TexCoord0;
varying lowp vec4 RenderDataOut;
varying lowp float ScaleOut;
varying lowp float TimeOut;
varying lowp float StrengthOut;

uniform sampler2D Texture0;
void main(void)
{
    vec4 original_color = Color0 * texture2D(Texture0, TexCoord0);
    vec2 coord = gl_FragCoord.xy / RenderDataOut.xy;
    float ratio = RenderDataOut.y / RenderDataOut.x;
    vec2 center = vec2(0.5);
    center.y *= ratio;
    coord.y *= ratio;

    float vignette = clamp(distance(coord, center), 0.0f, 1.0f);

    // maximum is 0.5f because we subtract FROM 0.5f (so 0.5f - 0.5f = 0)
    float final_strength = clamp(StrengthOut, 0.0f, 1.0f) * 0.5f;

    vignette = smoothstep(0.5f - (sin(TimeOut * 0.05f) * 0.5 + 0.5) * final_strength, 1.0f, vignette);

    vec4 Color = mix(original_color, vec4(1, 0, 0, 1), vignette);
    gl_FragColor = Color;
}
